static char const *
source_provenance(
        T2Checker *checker,
        Expr const *site,
        char const *description
)
{
        if (site == NULL || description == NULL) return description;
        usize described = strlen(description);
        u64 key = (u64)(uptr)site ^ hash64z(description);
        u32 head;
        usize previous = t2_index_find(&checker->provenance_index, key, &head)
                        ? head
                        : SIZE_MAX;
        for (usize i = previous; i != SIZE_MAX; i = v__(checker->provenances, i).previous) {
                T2Provenance const *entry = v_(checker->provenances, i);
                if (
                        entry->site == site
                     && strncmp(entry->text, description, described) == 0
                     && strncmp(entry->text + described, " at ", 4) == 0
                ) return entry->text;
        }
        char const *path = checker->path == NULL ? "<unknown>" : checker->path;
        char buffer[512];
        int length = ty_snprintf(
                buffer,
                sizeof buffer,
                "%s at %s:%u:%u",
                description,
                path,
                site->start.line + 1,
                site->start.col + 1
        );
        if (length < 0) return description;
        char *text = ty_malloc((usize)length + 1);
        if (text == NULL) {
                checker->failed = true;
                return description;
        }
        if ((usize)length < sizeof buffer) {
                memcpy(text, buffer, (usize)length + 1);
        } else {
                ty_snprintf(
                        text,
                        (usize)length + 1,
                        "%s at %s:%u:%u",
                        description,
                        path,
                        site->start.line + 1,
                        site->start.col + 1
                );
        }
        if (!t2_index_put(&checker->provenance_index, key, (u32)vN(checker->provenances))) {
                ty_free(text);
                checker->failed = true;
                return description;
        }
        xvP(checker->provenances, ((T2Provenance) {
                .site = site,
                .text = text,
                .previous = previous
        }));
        return text;
}

static bool
resize_nodes(T2Checker *checker, usize capacity)
{
        T2NodeInfo *nodes = ty_calloc(capacity, sizeof *nodes);

        if (nodes == NULL) {
                checker->failed = true;
                return false;
        }

        for (usize i = 0; i < checker->node_capacity; ++i) {
                T2NodeInfo node = checker->nodes[i];
                if (node.syntax == NULL) {
                        continue;
                }

                usize slot = ptr_hash(node.syntax) & (capacity - 1);
                while (nodes[slot].syntax != NULL) {
                        slot = (slot + 1) & (capacity - 1);
                }
                nodes[slot] = node;
        }

        ty_free(checker->nodes);
        checker->nodes = nodes;
        checker->node_capacity = capacity;

        return true;
}

